add_action( 'woocommerce_cart_calculate_fees', 'perfectpixel_fee_by_shipping_class' );

function perfectpixel_fee_by_shipping_class( $cart ) {
	if ( is_admin() && ! defined( 'DOING_AJAX' ) ) {
		return;
	}
	$class   = '{{fee_shipping_class}}';
	$amount  = (float) '{{fee_amount}}';
	$taxable = true;

	foreach ( $cart->get_cart() as $item ) {
		if ( ! empty( $item['data'] ) && $item['data']->get_shipping_class() === $class ) {
			$cart->add_fee( '{{fee_label}}', $amount, $taxable );
			return;
		}
	}
}
